(function(root){
 const E=id=>document.getElementById(id),names={ko:'한국어',ja:'일본어',en:'영어'};let notebooks=[],rows=[],current='',page=1,epoch=0,editing=null,provenance=null,bookEditing=null,busy=false,clean='',bookClean='',confirmAction=null;
 const node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e};
 function notify(){try{localStorage.setItem('aka.vocabulary.changed',Date.now()+':'+crypto.randomUUID())}catch{}}
 const message=t=>E('vocabStatus').textContent=t;
 function lock(on){busy=on;for(const id of ['vocabEntrySave','vocabEntryCancel','vocabBookSave','vocabBookCancel','vocabCreate','vocabRename','vocabDeleteBook','vocabNewEntry','vocabEntryCreateBook','vocabNotebook','vocabSearch','vocabEntryDelete','vocabManagerClose'])E(id).disabled=on;for(const e of [...E('vocabEditor').querySelectorAll('input,textarea,select'),...E('vocabBookEditor').querySelectorAll('input,textarea,select')])e.disabled=on;for(const b of E('vocabRows').querySelectorAll('button'))b.disabled=on}
 function fillBooks(select,value){select.replaceChildren();for(const b of notebooks){const o=node('option',b.icon+' '+b.name);o.value=b.id;select.append(o)}select.value=notebooks.some(b=>b.id===value)?value:notebooks[0]?.id||''}
 const filter=(items,query)=>{const q=VocabularyStore.normalize(query);return items.filter(r=>!q||VocabularyStore.normalize([r.word,r.reading,r.meaning].join(' ')).includes(q))};
 async function refresh(){const token=++epoch;try{notebooks=await VocabularyStore.books();if(token!==epoch)return;if(!notebooks.some(b=>b.id===current))current=notebooks[0]?.id||'';fillBooks(E('vocabNotebook'),current);rows=current?await VocabularyStore.entries(current):[];if(token!==epoch)return;draw()}catch(e){message('단어장을 열지 못했습니다: '+e.message)}}
 function draw(){const all=filter(rows,E('vocabSearch').value),pages=Math.max(1,Math.ceil(all.length/25));page=Math.max(1,Math.min(page,pages));E('vocabListCount').textContent=all.length+'개'+(E('vocabSearch').value?' / 전체 '+rows.length+'개':'');E('vocabListPage').textContent=page+' / '+pages;E('vocabPrev').disabled=page<=1;E('vocabNext').disabled=page>=pages;E('vocabRename').disabled=E('vocabDeleteBook').disabled=!current||busy;E('vocabEmpty').hidden=all.length>0;E('vocabEmpty').textContent=!notebooks.length?'단어장을 만들어 단어를 모아보세요.':rows.length?'검색 결과가 없습니다.':'저장한 단어가 없습니다.';const sources=E('vocabListSources');sources.replaceChildren();const seen=new Set();for(const r of all){const p=r.provenance;if(!p||seen.has(p.label+'|'+p.license))continue;seen.add(p.label+'|'+p.license);const a=node('a',p.label+' · '+p.license);a.href=p.url;a.target='_blank';a.rel='noopener noreferrer';if(sources.children.length)sources.append(document.createTextNode(' · '));sources.append(a)}sources.hidden=!seen.size;const host=E('vocabRows');host.replaceChildren();for(const r of all.slice((page-1)*25,page*25)){const tr=node('tr'),word=node('td'),meaning=node('td'),language=node('td'),actions=node('td');word.append(node('b',r.word));if(r.reading)word.append(node('small',r.reading));meaning.textContent=r.meaning;language.textContent=names[r.sourceLang]+' → '+names[r.targetLang];const edit=node('button','수정'),remove=node('button','삭제');edit.setAttribute('aria-label',r.word+' 수정');remove.setAttribute('aria-label',r.word+' 삭제');edit.disabled=remove.disabled=busy;edit.onclick=()=>openEntry(r,true);remove.onclick=()=>confirm('단어 삭제','“'+r.word+'” 항목을 삭제할까요?',async()=>{await VocabularyStore.removeEntry(r.id);notify();await refresh();SettingsUI.toast('단어를 삭제했습니다.')});actions.append(edit,remove);tr.append(word,meaning,language,actions);host.append(tr)}}
 async function open(){if(busy)return;E('vocabSearch').value='';page=1;message('');E('vocabManager').showModal();await refresh()}
 function draft(){return {notebook:E('vocabEntryNotebook').value,word:E('vocabWord').value,reading:E('vocabReading').value,sourceLang:E('vocabSource').value,targetLang:E('vocabTarget').value,meaning:E('vocabMeaning').value}}
 function bookDraft(){return {name:E('vocabBookName').value,icon:E('vocabBookIcon').value}}
 function changed(){return JSON.stringify(draft())!==clean}
 function sourceLabel(){const host=E('vocabProvenance');host.replaceChildren();host.hidden=!provenance;if(provenance){const p=node('p',provenance.label+' · '+provenance.version+' · '+provenance.license),a=node('a','원문 · 출처');a.href=provenance.url;a.target='_blank';a.rel='noopener noreferrer';host.append(p,a);if(E('vocabMeaning').value.trim()!==provenance.originalMeaning.trim())host.append(node('small','사전에서 가져온 뜻을 수정한 항목입니다.'))}}
 async function openEntry(seed={},isEdit=false,valid=()=>true){if(busy)return;const token=++epoch;try{await VocabularyStore.ensureDefault();notebooks=await VocabularyStore.books();if(token!==epoch||!valid())return;editing=isEdit?structuredClone(seed):null;provenance=seed.provenance?structuredClone(seed.provenance):null;let last='';try{last=localStorage.getItem('aka.vocabulary.lastNotebook')}catch{}fillBooks(E('vocabEntryNotebook'),seed.notebook||last||current);E('vocabWord').value=seed.word||'';E('vocabReading').value=seed.reading||'';E('vocabSource').value=seed.sourceLang||DictionaryUI.source(seed.word||'');E('vocabTarget').value=seed.targetLang||DictionaryUI.targets()[0];E('vocabMeaning').value=seed.meaning||'';E('vocabEntryTitle').textContent=isEdit?'단어 수정':'단어장에 추가';E('vocabEntryDelete').hidden=!isEdit;E('vocabEntryStatus').textContent=seed.word?.length>500?'선택한 내용이 깁니다. 단어나 짧은 표현으로 줄여 주세요.':seed.meaning?.length>12000?'뜻이 깁니다. 저장할 뜻을 12,000자 이내로 정리해 주세요.':'';sourceLabel();clean=JSON.stringify(draft());E('vocabEditor').showModal();E(seed.meaning?'vocabWord':'vocabMeaning').focus()}catch(e){SettingsUI.toast('단어장을 열지 못했습니다: '+e.message)}}
 function fromSelection(){if(BetaTranslation.isRunning())return;const word=E('inlineSource').value.trim();if(word)openEntry({word})}
 async function saveEntry(){if(busy)return;const d=draft(),r={...d,id:editing?.id||crypto.randomUUID(),expectedUpdatedAt:editing?.updatedAt,provenance};lock(true);try{const saved=await VocabularyStore.saveEntry(r,!!editing);try{localStorage.setItem('aka.vocabulary.lastNotebook',saved.notebook)}catch{}notify();current=saved.notebook;E('vocabEditor').close();editing=null;provenance=null;SettingsUI.toast('단어장에 저장했습니다.');if(E('vocabManager').open)await refresh()}catch(e){E('vocabEntryStatus').textContent='저장 실패: '+e.message}finally{lock(false)}}
 function openBook(isEdit=false){if(busy)return;const b=isEdit?notebooks.find(b=>b.id===current):null;if(isEdit&&!b)return;bookEditing=b?structuredClone(b):null;E('vocabBookTitle').textContent=b?'단어장 수정':'새 단어장';E('vocabBookName').value=b?.name||'';E('vocabBookIcon').value=b?.icon||'📘';E('vocabBookStatus').textContent='';bookClean=JSON.stringify(bookDraft());E('vocabBookEditor').showModal();E('vocabBookName').focus()}
 async function saveBook(){if(busy)return;lock(true);try{const b=await VocabularyStore.saveBook({...bookDraft(),id:bookEditing?.id||crypto.randomUUID()},!!bookEditing);notify();current=b.id;notebooks=await VocabularyStore.books();if(E('vocabEditor').open){fillBooks(E('vocabEntryNotebook'),b.id)}E('vocabBookEditor').close();if(E('vocabManager').open)await refresh();SettingsUI.toast('단어장을 저장했습니다.')}catch(e){E('vocabBookStatus').textContent='저장 실패: '+e.message}finally{lock(false)}}
 function confirm(title,text,action){if(busy)return;E('vocabConfirmTitle').textContent=title;E('vocabConfirmText').textContent=text;E('vocabConfirmStatus').textContent='';confirmAction=action;E('vocabConfirm').showModal()}
 async function acceptConfirm(){if(busy||!confirmAction)return;lock(true);E('vocabConfirmYes').disabled=E('vocabConfirmNo').disabled=true;try{await confirmAction();E('vocabConfirm').close();confirmAction=null}catch(e){E('vocabConfirmStatus').textContent='처리 실패: '+e.message}finally{lock(false);E('vocabConfirmYes').disabled=E('vocabConfirmNo').disabled=false;draw()}}
 function closeEntry(){if(busy)return;if(changed())confirm('편집 취소','저장하지 않은 내용을 버릴까요?',()=>{E('vocabEditor').close();editing=null;provenance=null;if(E('vocabManager').open)refresh()});else{E('vocabEditor').close();if(E('vocabManager').open)refresh()}}
 function closeBook(){if(busy)return;if(JSON.stringify(bookDraft())!==bookClean)confirm('편집 취소','저장하지 않은 단어장 설정을 버릴까요?',()=>E('vocabBookEditor').close());else E('vocabBookEditor').close()}
 function startArea(){if(busy||ReaderSelection.isPreparing()||ModelManager.isBusy()||BetaTranslation.isRunning()){SettingsUI.toast('현재 작업을 완료하거나 취소한 뒤 선택하세요.');return}if(BetaTranslation.isSelecting()){ReaderSelection.cancelPending('');return}ReaderSelection.invalidate('');BetaTranslation.selectVocabulary()}
 function init(){E('quickVocabulary').onclick=startArea;E('openVocabulary').onclick=open;E('inlineVocabulary').onclick=fromSelection;E('vocabManagerClose').onclick=()=>E('vocabManager').close();E('vocabCreate').onclick=E('vocabEntryCreateBook').onclick=()=>openBook();E('vocabRename').onclick=()=>openBook(true);E('vocabNewEntry').onclick=()=>openEntry({notebook:current});E('vocabNotebook').onchange=()=>{current=E('vocabNotebook').value;page=1;refresh()};E('vocabSearch').oninput=()=>{page=1;draw()};E('vocabPrev').onclick=()=>{page--;draw()};E('vocabNext').onclick=()=>{page++;draw()};E('vocabEntrySave').onclick=saveEntry;E('vocabEntryCancel').onclick=closeEntry;E('vocabBookSave').onclick=saveBook;E('vocabBookCancel').onclick=closeBook;E('vocabMeaning').oninput=sourceLabel;E('vocabDeleteBook').onclick=()=>{const b=notebooks.find(b=>b.id===current);if(b)confirm('단어장 삭제',b.icon+' '+b.name+'와 저장된 단어 '+rows.length+'개를 삭제할까요?',async()=>{await VocabularyStore.removeBook(b.id);notify();current='';await refresh();SettingsUI.toast('단어장을 삭제했습니다.')})};E('vocabEntryDelete').onclick=()=>{if(editing)confirm('단어 삭제','이 항목을 삭제할까요?',async()=>{await VocabularyStore.removeEntry(editing.id);notify();E('vocabEditor').close();editing=null;if(E('vocabManager').open)await refresh()})};E('vocabConfirmYes').onclick=acceptConfirm;E('vocabConfirmNo').onclick=()=>{if(!busy)E('vocabConfirm').close()};for(const [id,close]of [['vocabEditor',closeEntry],['vocabBookEditor',closeBook]])E(id).addEventListener('cancel',e=>{e.preventDefault();close()});for(const id of ['vocabManager','vocabConfirm'])E(id).addEventListener('cancel',e=>{if(busy)e.preventDefault()});window.addEventListener('storage',e=>{if(e.key==='aka.vocabulary.changed'&&E('vocabManager').open&&!busy)refresh()})}
 root.VocabularyUI={init,open,openEntry,filter,fromSelection};
})(globalThis);
VocabularyUI.init();
